#![allow(unused)]
verus! {

    /// An operation selector: addition, multiplication,
    /// logical-and, or logical-or over `i8`.
    enum OpType {
        Add,
        Multiply,
        LogicalAnd,
        LogicalOr,
    }

    /// A specification-level function giving the semantics
    /// of the four operations on `i8`.
    spec fn semantic(op: OpType, x: i8, y: i8) -> i8 {
        match op {
            OpType::Add => x + y,
            OpType::Multiply => x * y,
            OpType::LogicalAnd => if x != 0 && y != 0 { 1 } else { 0 },
            OpType::LogicalOr  => if x != 0 || y != 0 { 1 } else { 0 },
        }
    }

    /// Returns the identity element for the chosen operation,
    /// or `None` if no identity exists.
    ///
    /// Specification:
    /// - If `Some(id)` is returned, then `id` is an identity element:
    ///     forall x.  semantic(op, x, id) == x  &&  semantic(op, id, x) == x
    /// - If `None` is returned, then no integer is an identity.
    #[verifier(decreases_by = |_op| 0)]
    fn ufunc_identity(op: OpType) -> Option<i8>
        ensures
            // exactly the intended return value for each case
            match op {
                OpType::Add        => result == Some(0),
                OpType::Multiply   => result == Some(1),
                OpType::LogicalAnd => result.is_None(),
                OpType::LogicalOr  => result.is_None(),
            }
        ensures
            // If we return Some(id), then `id` is a two‐sided identity.
            (result.is_Some() ==>
                forall|x: i8| {
                    let id = result.get_Some_0();
                    semantic(op, x, id) == x
                    && semantic(op, id, x) == x
                })
            &&
            // If we return None, we witness that no integer can be
            // an identity by showing failure already on x = 2.
            (result.is_None() ==>
                forall|id_candidate: i8|
                    semantic(op, 2, id_candidate) != 2
            )
    {
        match op {
            OpType::Add => {
                let id: i8 = 0;
                proof {
                    // 0 + x = x and x + 0 = x for all x
                    assert(forall|x: i8| semantic(OpType::Add, x, 0) == x);
                    assert(forall|x: i8| semantic(OpType::Add, 0, x) == x);
                }
                Some(id)
            }

            OpType::Multiply => {
                let id: i8 = 1;
                proof {
                    // 1 * x = x and x * 1 = x for all x
                    assert(forall|x: i8| semantic(OpType::Multiply, x, 1) == x);
                    assert(forall|x: i8| semantic(OpType::Multiply, 1, x) == x);
                }
                Some(id)
            }

            OpType::LogicalAnd => {
                proof {
                    // For logical-and, for any id and x=2,
                    // semantic(LogicalAnd, 2, id) ∈ {0,1} ≠ 2
                    assert(forall|id: i8| semantic(OpType::LogicalAnd, 2, id) != 2);
                }
                None
            }

            OpType::LogicalOr => {
                proof {
                    // For logical-or, for any id and x=2,
                    // semantic(LogicalOr, 2, id) ∈ {0,1} ≠ 2
                    assert(forall|id: i8| semantic(OpType::LogicalOr, 2, id) != 2);
                }
                None
            }
        }
    }

}